go.solution:
package main

import "fmt"

func digitSum(n int) int {
	total := 0
	for n > 0 {
		total += n % 10
		n /= 10
	}
	return total
}

func main() {
	var n int
	fmt.Scan(&n)
	fmt.Println(digitSum(n))
}
